=== FILE: rr_arbiter.v ===
`timescale 1ns / 1ps
// rr_arbiter: round-robin arbiter for N requesters (default 4).
// Implements interface_spec.md and microarchitecture.md (prj-5041006167).
//   * ptr is the only state: index of the highest-priority requester.
//   * grant is combinational from req and ptr (same-cycle grant).
//   * The search walks from ptr upwards and wraps explicitly at LAST (N-1),
//     so an N that is not a power of two is handled.
//   * On a rising edge with a grant, ptr moves to one past the winner;
//     with no request, ptr holds.
//   * rst_n is synchronous, active low; ptr resets to 0. grant is not gated
//     by reset.
module rr_arbiter #(
    parameter integer N = 4
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire [N-1:0] req,
    output wire [N-1:0] grant
);

    localparam integer  PW     = $clog2(N);
    localparam [31:0]   LAST32 = N - 1;
    localparam [PW-1:0] LAST   = LAST32[PW-1:0];
    localparam [31:0]   ONE32  = 32'd1;
    localparam [PW-1:0] ONE    = ONE32[PW-1:0];

    reg  [PW-1:0] ptr;
    reg  [PW-1:0] ptr_next;
    reg  [PW-1:0] winner;
    reg           any_req;
    reg  [PW-1:0] idx;
    integer       k;

    // Wrapping priority search from ptr; defaults first, so no latch.
    always @* begin
        winner   = {PW{1'b0}};
        any_req  = 1'b0;
        idx      = ptr;
        for (k = 0; k < N; k = k + 1) begin
            if (!any_req && req[idx]) begin
                winner  = idx;
                any_req = 1'b1;
            end
            if (idx == LAST) idx = {PW{1'b0}};
            else             idx = idx + ONE;
        end
        ptr_next = ptr;
        if (any_req) begin
            if (winner == LAST) ptr_next = {PW{1'b0}};
            else                ptr_next = winner + ONE;
        end
    end

    // One-hot grant decoded from the winner index.
    genvar g;
    generate
        for (g = 0; g < N; g = g + 1) begin : g_grant
            localparam [31:0]   IDX32 = g;
            localparam [PW-1:0] IDX   = IDX32[PW-1:0];
            assign grant[g] = any_req && (winner == IDX);
        end
    endgenerate

    // Pointer register: reset value and update only.
    always @(posedge clk) begin
        if (!rst_n) ptr <= {PW{1'b0}};
        else        ptr <= ptr_next;
    end

`ifdef FORMAL
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    always @(*) begin
        if (!f_past_valid) assume (!rst_n);
    end

    // Distance from the pointer to the winner, searching upwards.
    wire [PW:0] f_wdist = (winner >= ptr) ? (winner - ptr) : (winner + N - ptr);

    always @(posedge clk) begin
        if (f_past_valid) begin
            assert (ptr <= LAST);
            assert ((grant & (grant - 1'b1)) == {N{1'b0}});
            assert ((grant & ~req) == {N{1'b0}});
            assert ((req == {N{1'b0}}) || (grant != {N{1'b0}}));
            assert (any_req == (req != {N{1'b0}}));
        end
        if (f_past_valid && !$past(rst_n))
            assert (ptr == {PW{1'b0}});
        if (f_past_valid && $past(rst_n) && $past(any_req))
            assert (ptr == (($past(winner) == LAST) ? {PW{1'b0}} : ($past(winner) + ONE)));
        if (f_past_valid && $past(rst_n) && !$past(any_req))
            assert (ptr == $past(ptr));
    end

    always @(posedge clk) begin
        if (f_past_valid && rst_n)
            cover (req == {N{1'b1}});
        if (f_past_valid && $past(rst_n) && $past(any_req))
            cover (($past(ptr) == LAST) && (ptr == {PW{1'b0}}));
    end

    genvar fi;
    generate
        for (fi = 0; fi < N; fi = fi + 1) begin : g_fair
            reg  [PW:0] f_wait;
            wire [PW:0] f_dist = (fi >= ptr) ? (fi - ptr) : (fi + N - ptr);

            always @(posedge clk) begin
                if (!rst_n)                     f_wait <= {(PW+1){1'b0}};
                else if (req[fi] && !grant[fi]) f_wait <= f_wait + 1'b1;
                else                            f_wait <= {(PW+1){1'b0}};
            end

            always @(posedge clk) begin
                if (f_past_valid) begin
                    assert (f_wait <= N - 1);
                    assert (f_wait + f_dist <= N - 1);
                    assert (grant[fi] == (any_req && (winner == fi)));
                    if (any_req && req[fi])
                        assert (f_dist >= f_wdist);
                end
            end

            always @(posedge clk) begin
                if (f_past_valid && rst_n) begin
                    cover (grant[fi]);
                    cover (f_wait == N - 1);
                end
            end
        end
    endgenerate
`endif

endmodule

`ifdef FORMAL
// Formal-only top: the same proof at a power of two (N 4) and not (N 5).
module rr_arbiter_formal (
    input  wire       clk,
    input  wire       rst_n,
    input  wire [3:0] req4,
    input  wire [4:0] req5,
    output wire [3:0] grant4,
    output wire [4:0] grant5
);
    rr_arbiter #(.N(4)) u_n4 (.clk(clk), .rst_n(rst_n), .req(req4), .grant(grant4));
    rr_arbiter #(.N(5)) u_n5 (.clk(clk), .rst_n(rst_n), .req(req5), .grant(grant5));
endmodule
`endif
