`timescale 1ns / 1ps
// Self-checking testbench for rr_arbiter: N 4 and N 5 side by side.

module rr_arbiter_tb_unit #(
    parameter integer N    = 4,
    parameter integer SEED = 1
) (
    input  wire        clk,
    output reg         done,
    output wire [31:0] passed,
    output wire [31:0] failed
);

    reg  [N-1:0] req;
    reg          rst_n;
    wire [N-1:0] grant;
    reg          rot_mode;

    rr_arbiter #(.N(N)) dut (
        .clk   (clk),
        .rst_n (rst_n),
        .req   (req),
        .grant (grant)
    );

    // ---------------- checker (owns its variables) ----------------
    integer     armed      = 0;
    integer     ran        = 0;
    integer     m_ptr      = 0;
    integer     chk_pass   = 0;
    integer     chk_fail   = 0;
    integer     rot_count  = 0;
    integer     prev_valid = 0;
    integer     exp_idx    = -1;
    integer     ck, cj, ci, nreq;
    integer     wcnt [0:N-1];
    reg [N-1:0] exp_grant;
    reg [N-1:0] rot_exp;
    reg [N-1:0] prev_req   = {N{1'b0}};
    reg [N-1:0] last_grant = {N{1'b0}};
    reg         fair_ok;
    reg         others_changed;
    reg         cov_none    = 1'b0;
    reg         cov_all     = 1'b0;
    reg         cov_held    = 1'b0;
    reg         cov_maxwait = 1'b0;
    reg         cov_rst     = 1'b0;
    reg [N-1:0] cov_alone   = {N{1'b0}};

    always @(posedge clk) begin
        if (armed != 0) begin
            // Reference pointer model: first requester at or after m_ptr.
            exp_grant = {N{1'b0}};
            exp_idx   = -1;
            for (ck = 0; ck < N; ck = ck + 1) begin
                cj = (m_ptr + ck) % N;
                if (exp_idx < 0 && req[cj]) exp_idx = cj;
            end
            if (exp_idx >= 0) exp_grant[exp_idx] = 1'b1;
            if (grant === exp_grant) begin
                chk_pass = chk_pass + 1;
            end else begin
                chk_fail = chk_fail + 1;
                $error("rr_arbiter N=%0d t=%0t: req=%b grant=%b expected=%b (model ptr %0d)",
                       N, $time, req, grant, exp_grant, m_ptr);
            end

            // Strict rotation after reset with everyone requesting.
            if (rst_n !== 1'b1) begin
                rot_count = 0;
            end else if (rot_mode) begin
                rot_exp = {N{1'b0}};
                rot_exp[rot_count % N] = 1'b1;
                if (grant === rot_exp) begin
                    chk_pass = chk_pass + 1;
                end else begin
                    chk_fail = chk_fail + 1;
                    $error("rr_arbiter N=%0d t=%0t: rotation step %0d grant=%b expected=%b",
                           N, $time, rot_count, grant, rot_exp);
                end
                rot_count = rot_count + 1;
            end

            // Fairness: a held request waits at most N-1 cycles.
            fair_ok = 1'b1;
            for (ci = 0; ci < N; ci = ci + 1) begin
                if (rst_n !== 1'b1) begin
                    wcnt[ci] = 0;
                end else if (req[ci] && !grant[ci]) begin
                    wcnt[ci] = wcnt[ci] + 1;
                    if (wcnt[ci] > N - 1) fair_ok = 1'b0;
                    if (wcnt[ci] == N - 1) cov_maxwait = 1'b1;
                end else begin
                    wcnt[ci] = 0;
                end
            end
            if (fair_ok) begin
                chk_pass = chk_pass + 1;
            end else begin
                chk_fail = chk_fail + 1;
                $error("rr_arbiter N=%0d t=%0t: a held request waited more than %0d cycles",
                       N, $time, N - 1);
            end

            // Coverage.
            nreq = 0;
            for (ci = 0; ci < N; ci = ci + 1)
                if (req[ci]) nreq = nreq + 1;
            if (rst_n === 1'b1) begin
                ran = 1;
                if (nreq == 0) cov_none = 1'b1;
                if (nreq == N) cov_all  = 1'b1;
                if (nreq == 1) begin
                    for (ci = 0; ci < N; ci = ci + 1)
                        if (req[ci]) cov_alone[ci] = 1'b1;
                end
                if (prev_valid != 0) begin
                    for (ci = 0; ci < N; ci = ci + 1) begin
                        if (req[ci] && prev_req[ci] && !last_grant[ci]) begin
                            others_changed = 1'b0;
                            for (cj = 0; cj < N; cj = cj + 1)
                                if (cj != ci && req[cj] != prev_req[cj]) others_changed = 1'b1;
                            if (others_changed) cov_held = 1'b1;
                        end
                    end
                end
                prev_valid = 1;
            end else begin
                if (ran != 0 && nreq > 0) cov_rst = 1'b1;
                prev_valid = 0;
            end
            prev_req = req;
        end

        last_grant = grant;

        if (rst_n === 1'b0) begin
            armed = 1;
            m_ptr = 0;
        end else if (armed != 0 && exp_idx >= 0) begin
            m_ptr = (exp_idx + 1) % N;
        end
    end

    // ---------------- stimulus (owns its variables) ----------------
    integer      cov_pass = 0;
    integer      cov_fail = 0;
    integer      si, sc, sh, hreq;
    reg [31:0]   rng;

    assign passed = chk_pass + cov_pass;
    assign failed = chk_fail + cov_fail;

    function [31:0] xs32(input [31:0] s);
        reg [31:0] x;
        begin
            x = s;
            x = x ^ (x << 13);
            x = x ^ (x >> 17);
            x = x ^ (x << 5);
            xs32 = x;
        end
    endfunction

    function [N-1:0] onehot(input integer b);
        begin
            onehot    = {N{1'b0}};
            onehot[b] = 1'b1;
        end
    endfunction

    initial begin
        done     = 1'b0;
        rng      = SEED;
        req      = {N{1'b0}};
        rst_n    = 1'b0;
        rot_mode = 1'b0;

        // Initial reset, no traffic.
        repeat (3) @(negedge clk);
        rst_n = 1'b1;

        // No requests.
        repeat (3) @(negedge clk);

        // Each requester alone.
        for (si = 0; si < N; si = si + 1) begin
            req = onehot(si);
            repeat (2) @(negedge clk);
        end

        // Reset during traffic, then everyone requesting: strict rotation.
        req   = {N{1'b1}};
        rst_n = 1'b0;
        repeat (2) @(negedge clk);
        rst_n    = 1'b1;
        rot_mode = 1'b1;
        repeat (3 * N) @(negedge clk);
        rot_mode = 1'b0;

        // A held request among changing others (lowest and highest index).
        for (sh = 0; sh < 2; sh = sh + 1) begin
            hreq = (sh == 0) ? 0 : N - 1;
            for (sc = 0; sc < 4 * N; sc = sc + 1) begin
                rng = xs32(rng);
                req = rng[N-1:0] | onehot(hreq);
                @(negedge clk);
            end
        end

        // Hold-until-granted random traffic, requests dropped and raised,
        // with occasional reset during traffic.
        for (sc = 0; sc < 300; sc = sc + 1) begin
            rng = xs32(rng);
            for (si = 0; si < N; si = si + 1) begin
                if (req[si] && !last_grant[si]) req[si] = 1'b1;
                else                            req[si] = rng[si];
            end
            rst_n = (rng[31:26] != 6'd0);
            @(negedge clk);
        end

        rst_n = 1'b1;
        req   = {N{1'b0}};
        repeat (2) @(negedge clk);

        // Coverage goals.
        if (cov_none) cov_pass = cov_pass + 1;
        else begin cov_fail = cov_fail + 1; $error("rr_arbiter N=%0d: coverage not reached: no requests", N); end
        if (cov_all) cov_pass = cov_pass + 1;
        else begin cov_fail = cov_fail + 1; $error("rr_arbiter N=%0d: coverage not reached: everyone requesting", N); end
        if (cov_held) cov_pass = cov_pass + 1;
        else begin cov_fail = cov_fail + 1; $error("rr_arbiter N=%0d: coverage not reached: held request among changing others", N); end
        if (cov_maxwait) cov_pass = cov_pass + 1;
        else begin cov_fail = cov_fail + 1; $error("rr_arbiter N=%0d: coverage not reached: longest fair wait", N); end
        if (cov_rst) cov_pass = cov_pass + 1;
        else begin cov_fail = cov_fail + 1; $error("rr_arbiter N=%0d: coverage not reached: reset during traffic", N); end
        for (si = 0; si < N; si = si + 1) begin
            if (cov_alone[si]) cov_pass = cov_pass + 1;
            else begin cov_fail = cov_fail + 1; $error("rr_arbiter N=%0d: coverage not reached: requester %0d alone", N, si); end
        end

        done = 1'b1;
    end

endmodule

module rr_arbiter_tb;

    reg            clk;
    reg [8*64-1:0] nonce;
    integer        got;
    integer        passed;
    integer        failed;
    wire           done4;
    wire           done5;
    wire [31:0]    p4;
    wire [31:0]    f4;
    wire [31:0]    p5;
    wire [31:0]    f5;

    rr_arbiter_tb_unit #(.N(4), .SEED(305419896)) u_n4 (
        .clk(clk), .done(done4), .passed(p4), .failed(f4)
    );

    rr_arbiter_tb_unit #(.N(5), .SEED(195939070)) u_n5 (
        .clk(clk), .done(done5), .passed(p5), .failed(f5)
    );

    initial begin
        clk = 1'b0;
        forever #5 clk = ~clk;
    end

    initial begin
        nonce = {(8*64){1'b0}};
        got   = $value$plusargs("nirmaan_nonce=%s", nonce);
        wait (done4 && done5);
        passed = p4 + p5;
        failed = f4 + f5;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

    initial begin
        #1000000;
        $error("rr_arbiter_tb: timeout before both units finished");
        passed = p4 + p5;
        failed = f4 + f5 + 1;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
=== END FILE ===
